sys_script_include.script:
var OutboundEventProcessor = Class.create();
OutboundEventProcessor.prototype = {
    initialize: function() {},

    process: function(target) {

        var gr = new GlideRecord('x_1044869_tomek_0_outbound_event');
        gr.addQuery('u_target', target);
        gr.addQuery('u_status', 'NEW');
		gr.addQuery('u_retry_count', '<', 5);
        gr.orderBy('sys_created_on');
        gr.setLimit(50);
        gr.query();

        while (gr.next()) {
            try {
				gs.info('Outbound Event processing: ' + gr.sys_id);
                gr.u_status = 'PROCESSING';
                gr.update();
                this.sendEvent(gr);

                gr.u_status = 'SENT';
                gr.update();
				gs.info('Outbound Event SENT: ' + gr.sys_id);
            } catch (err) {
                gr.u_status = 'ERROR';
                gr.u_last_error = err.message;
                gr.u_retry_count = (gr.u_retry_count || 0) + 1;
                gr.update();
            }

        }

    },

    sendEvent: function(grObj) {

        var payloadToNiFi = grObj.u_payload;
        var r = new sn_ws.RESTMessageV2('x_1044869_tomek_0.NiFi webserver', 'POST');
        r.setStringParameterNoEscape('payload', payloadToNiFi);

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

		if (httpStatus <200 || httpStatus >= 300){
			throw new Error('HTTP error: ' + httpStatus);
		}

    },

	testProcessor: function(input){
		gs.info("Provided input: " + input);

		return "SUCCESS";
	},

    type: 'OutboundEventProcessor'
};
